import React from 'react';

const alerts = [
  { icon: '🔥', label: 'Fire Detected',      cam: 'Camera 02 - Parking',   time: '10:30:21 AM', sev: 'High',   sc: '#f87171', sb: '#450a0a' },
  { icon: '⚡', label: 'Violence Detected',   cam: 'Camera 03 - Corridor',  time: '10:29:15 AM', sev: 'High',   sc: '#f87171', sb: '#450a0a' },
  { icon: '🔫', label: 'Gun Detected',        cam: 'Camera 01 - Main Gate', time: '10:28:05 AM', sev: 'High',   sc: '#f87171', sb: '#450a0a' },
  { icon: '🏃', label: 'Falling Detected',    cam: 'Camera 04 - Office',    time: '10:27:42 AM', sev: 'Medium', sc: '#fbbf24', sb: '#2d220a' },
  { icon: '🎭', label: 'Theft Mask Detected', cam: 'Camera 01 - Main Gate', time: '10:26:33 AM', sev: 'Medium', sc: '#fbbf24', sb: '#2d220a' },
];

export default function AlertsPanel() {
  return (
    <div style={{ borderBottom: '1px solid #1e2d47', padding: '10px 12px', flexShrink: 0 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8 }}>
        <span style={{ fontSize: 11, fontWeight: 700, color: '#94a3b8', textTransform: 'uppercase', letterSpacing: '.5px' }}>Recent Alerts</span>
        <span style={{ fontSize: 10, color: '#3b82f6', cursor: 'pointer' }}>View All</span>
      </div>

      {alerts.map((a, i) => (
        <div key={i} style={{
          display: 'flex', alignItems: 'center', gap: 8,
          padding: '5px 0',
          borderBottom: i < alerts.length - 1 ? '1px solid #1e2d47' : 'none'
        }}>
          <span style={{ fontSize: 18, width: 26, textAlign: 'center', flexShrink: 0 }}>{a.icon}</span>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: 11, fontWeight: 600, color: '#fff' }}>{a.label}</div>
            <div style={{ fontSize: 10, color: '#64748b', marginTop: 1 }}>{a.cam}</div>
          </div>
          <div style={{ textAlign: 'right', flexShrink: 0 }}>
            <div style={{ fontSize: 10, color: '#64748b' }}>{a.time}</div>
            <span style={{ fontSize: 9, fontWeight: 700, padding: '2px 6px', borderRadius: 3, background: a.sb, color: a.sc, display: 'inline-block', marginTop: 2 }}>
              {a.sev}
            </span>
          </div>
        </div>
      ))}
    </div>
  );
}
